async function ensureClicks(db) {
  await db.prepare('CREATE TABLE IF NOT EXISTS expomar_clicks (formulario TEXT PRIMARY KEY, total INTEGER NOT NULL)').run();
}

async function galleryItems(db) {
  await db.prepare('CREATE TABLE IF NOT EXISTS expomar_gallery (id INTEGER PRIMARY KEY, tipo TEXT NOT NULL, url TEXT NOT NULL, titulo TEXT NOT NULL)').run();
  return (await db.prepare('SELECT id,tipo,url,titulo FROM expomar_gallery ORDER BY id DESC').all()).results;
}

function mediaMarkup(item) {
  const title = esc(item.titulo);
  const source = esc(item.url);
  if (item.tipo === 'foto') return '<figure><img loading="lazy" src="'+source+'" alt="'+title+'"><figcaption>'+title+'</figcaption></figure>';
  const url = new URL(item.url);
  const youtubeId = url.hostname === 'youtu.be' ? url.pathname.slice(1) : ['youtube.com','www.youtube.com','m.youtube.com'].includes(url.hostname) ? url.searchParams.get('v') || url.pathname.match(/^\/(?:shorts|embed)\/([^/]+)$/)?.[1] : '';
  if (/^[\w-]{11}$/.test(youtubeId || '')) return '<figure><iframe loading="lazy" title="'+title+'" src="https://www.youtube-nocookie.com/embed/'+youtubeId+'" allowfullscreen></iframe><figcaption>'+title+'</figcaption></figure>';
  if (/\.(mp4|webm)$/i.test(url.pathname)) return '<figure><video controls preload="none" src="'+source+'"></video><figcaption>'+title+'</figcaption></figure>';
  return '<figure><figcaption><a href="'+source+'" target="_blank" rel="noopener noreferrer">'+title+'</a></figcaption></figure>';
}

async function galleryAdmin(req, url, db) {
  const items = await galleryItems(db);
  if (req.method === 'POST') {
    if (req.headers.get('Origin') !== url.origin) return new Response('Origen inválido', {status:403});
    const data = await req.formData();
    const type = String(data.get('tipo') || '');
    const title = String(data.get('titulo') || '').trim();
    let mediaUrl;
    try { mediaUrl = new URL(String(data.get('url') || '')); } catch {}
    if (!mediaUrl || mediaUrl.protocol !== 'https:' || mediaUrl.username || mediaUrl.password || mediaUrl.href.length > 2000 || !['foto','video'].includes(type) || !title || title.length > 120) {
      return page('Revisa los datos', '<p>Usa un enlace HTTPS público y un título de hasta 120 caracteres.</p><a href="/gerencia/galeria">Volver</a>');
    }
    await db.prepare('INSERT INTO expomar_gallery(tipo,url,titulo) VALUES (?,?,?)').bind(type,mediaUrl.href,title).run();
    return Response.redirect(new URL('/gerencia/galeria', url),303);
  }
  return page('Galería de Expomar', '<p><a href="/gerencia">Volver a gerencia</a> · <a href="/expomar">Ver landing</a></p><p>Para fotos, pega el enlace directo a la imagen. Para videos, usa un enlace de YouTube, un archivo MP4 o WebM, o un enlace público para abrir el video.</p><form method="post"><p><label>Tipo <select name="tipo"><option value="foto">Foto</option><option value="video">Video</option></select></label></p><p><label>Título <input name="titulo" required maxlength="120"></label></p><p><label>Enlace HTTPS <input name="url" type="url" required maxlength="2000"></label></p><button>Publicar en la galería</button></form><h2>Publicados</h2><ul>'+items.map(item=>'<li>'+esc(item.titulo)+' · '+esc(item.tipo)+'</li>').join('')+'</ul>');
}

